metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who buys books online"
        bookshop = softwareSystem "Bookshop" "An online bookshop" {
            webStore = container "Web Store" "Lets customers browse the catalogue and place orders" "Web application"
            orderProcessor = container "Order Processor" "Processes orders and coordinates fulfilment" "Service"
        }

        customer -> webStore "Browses books and places orders using" "HTTPS/JSON"
        webStore -> orderProcessor "Sends orders to" "REST/JSON"
    }

    views {
        systemContext bookshop "SystemContext" "Shows the Bookshop and its external actors" {
            include *
            autoLayout
        }
    }
}
